class Solution {
    public String rearrangeString(String s, char x, char y) {
        StringBuilder front = new StringBuilder(), rest = new StringBuilder();
        for (char c : s.toCharArray()) {
            if (c == y) front.append(c);
            else rest.append(c);
        }
        return front.append(rest).toString();
    }
}

